111:function startCombat(){caveObjects.forEach(o=>o.visible=false);street.visible=true;scene.background=new THREE.Color(0x101720);scene.fog=new THREE.FogExp2(0x101720,.018);player.position.set(0,0,7);player.rotation.y=0;yaw=0;pitch=0;heroHealth=100;attackCooldown=0;dodgeCooldown=0;gliding=false;glideVelocity=0;bossArrived=false;enemies.forEach((e,i)=>{e.group.visible=true;e.group.position.set((i-1)*3,0,-5-(i%2));e.hp=3;e.dead=false;e.boss=false;e.cooldown=1+i*.5;e.stun=0;e.group.scale.setScalar(1)});combat=true;gameActive=true;document.body.classList.add('combat-mode');$('#combatHud').classList.add('show');$('#chapterLabel').textContent='CHAPTER 02 — THE EAST END';$('#objectiveTitle').textContent='Protect the street';$('#objectiveText').textContent='Stop the attackers. F to strike, R to guard, Shift to dodge. Hold Space to leap and glide.';$('#fightTip').textContent='F / HIT · R / GUARD · SHIFT / DODGE · SPACE / GLIDE';updateCombatHud();showToast('THE CITY DOESN’T WAIT');startDialogue([['ALFRED','Sir—there’s trouble on the east end. Three men cornered a shopkeeper.'],['BRUCE','I’m on my way.'],['ALFRED','Remember: protect the people first. You can take a hit. They shouldn’t have to.']])}
113:function strike(){if(!combat||dialogueBusy||attackCooldown>0)return;attackCooldown=.48;const forward=new THREE.Vector3(Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y));let target=null,best=2.35;for(const e of enemies){if(e.dead)continue;const d=new THREE.Vector3(e.group.position.x-player.position.x,0,e.group.position.z-player.position.z);let distance=d.length();if(Math.abs(e.group.position.y-player.position.y)<1.55&&distance<best&&(distance<.85||forward.dot(d.normalize())>.15)){best=distance;target=e}}if(target){target.hp--;target.stun=.65;const push=new THREE.Vector3(target.group.position.x-player.position.x,0,target.group.position.z-player.position.z).normalize();target.group.position.addScaledVector(push,.75);target.group.rotation.y=Math.atan2(push.x,-push.z);target.group.scale.setScalar(.9);setTimeout(()=>{if(target.group)target.group.scale.setScalar(1)},130);if(target.hp<=0){target.dead=true;target.group.visible=false;showToast('THREAT DISARMED')}else showToast('CLEAN HIT')}else showToast('CLOSE THE DISTANCE');updateCombatHud();if(enemies.every(e=>e.dead)){if(!bossArrived){bossArrived=true;$('#waveLabel').textContent='THE ROMAN';$('#objectiveTitle').textContent='Face Black Mask';$('#objectiveText').textContent='A crime boss has come to reclaim the street. Stay mobile, close the distance, and stop him.';makeEnemy(0,-11,3,true);showToast('THE ROMAN HAS ARRIVED');startDialogue([['BLACK MASK','You put my men on the pavement. That was a mistake.'],['BRUCE','This neighborhood isn’t yours.'],['BLACK MASK','Everything is mine. Let’s see how long that suit lasts.']]);updateCombatHud()}else{showToast('THE SHOPKEEPER IS SAFE');setTimeout(()=>finishCombat(true),800)}}}
